protected function setUp(): void
{
    parent::setUp();

    Http::preventStrayRequests();
}

public function test_it_answers_502_when_the_carrier_is_down(): void
{
    Http::fake([
        'api.carrier.example/*' => Http::response(['error' => 'maintenance'], 503),
    ]);

    $this->actingAs(User::factory()->create())
        ->postJson('/api/quotes', ['postal_code' => '1500001', 'weight_grams' => 1200])
        ->assertStatus(502)
        ->assertJsonPath('message', 'Carrier unavailable');

    $this->assertDatabaseCount('quotes', 0);
}
